  select count(*) into v_tests from public.practice_tests where id in ('pt-sb-rate-limiting', 'pt-sb-introduction-to-microservices-with-spring-boot', 'pt-sb-kafka-with-spring-boot', 'pt-sb-docker-for-spring-boot', 'pt-sb-deploying-spring-boot-application', 'pt-sb-spring-boot-interview-questions', 'pt-sb-spring-boot-mini-project') and learning_topic_id is not null;
